class InvalidForkAggregateChainError(ValueError):
    """A fork aggregate successor, chain binding or anchor is invalid."""


def _fac_chain_invalid(message: str) -> InvalidForkAggregateChainError:
    return InvalidForkAggregateChainError(
        f"invalid fork aggregate chain: {message}"
    )


def _reject_duplicate_fac_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate successor keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _fac_chain_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


# -- Stage views over a root fork-decision aggregate or successor --------------

def _fac_root_view(raw: bytes) -> dict:
    """Structurally parse a root fork-decision aggregate predecessor."""
    payload, _signature = _parse_pfda(raw)
    return {
        "kind": "root",
        FAC_ROOT_DIGEST: hashlib.sha256(raw).hexdigest(),
        FAC_HEIGHT: 0,
        STATUS: payload[STATUS],
        PFDA_DECLARATION: payload[PFDA_DECLARATION],
        PFDA_INPUTS: list(payload[PFDA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[PFDA_PRUNE_POLICY_DIGEST],
        "site_policy_digest": payload[PFDA_SITE_POLICY_DIGEST],
        "policy_digest": payload[PFDA_DECISION_SITE_POLICY_DIGEST],
        FAC_POLICY_VERSION: PRUNE_FORK_DECISION_AGGREGATE_VERSION,
        FAC_EFFECTIVE_AT: None,
    }


def _fac_successor_view(raw: bytes) -> dict:
    """Structurally parse a fork aggregate successor predecessor."""
    payload, _signature, _increment = _parse_fac_successor(raw)
    return {
        "kind": "successor",
        FAC_ROOT_DIGEST: payload[FAC_ROOT_DIGEST],
        FAC_HEIGHT: payload[FAC_HEIGHT],
        STATUS: payload[STATUS],
        PFDA_DECLARATION: copy.deepcopy(payload[PFDA_DECLARATION]),
        PFDA_INPUTS: list(payload[PFDA_INPUTS]),
        PA_ITEMS: copy.deepcopy(payload[ITEMS]),
        "prune_policy_digest": payload[PFDA_PRUNE_POLICY_DIGEST],
        "site_policy_digest": payload[FAC_SITE_POLICY_DIGEST],
        "policy_digest": payload[FAC_NEW_POLICY_DIGEST],
        FAC_POLICY_VERSION: payload[FAC_POLICY_VERSION],
        FAC_EFFECTIVE_AT: payload[FAC_EFFECTIVE_AT],
    }


def _fac_predecessor_view(raw: object) -> dict:
    """Parse predecessor bytes (root aggregate or successor packet).

    The packet kind is chosen from the payload key set so a malformed
    root raises :class:`InvalidAggregateForkDecisionAggregateError`
    while a malformed successor raises
    :class:`InvalidForkAggregateChainError`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("predecessor must be bytes")
    keys = _packet_payload_keys(raw)
    if keys is not None and FAC_ROOT_DIGEST in keys:
        return _fac_successor_view(raw)
    return _fac_root_view(raw)


# -- Recomputing one stage verdict from prefix plus decision increment ---------

def _fac_recompute(
    prefix_inputs: list[str],
    prefix_rows: list[dict],
    increment: list[dict],
    prune_policy_digest: str,
    fork_site_policy_digest: str,
    fork_threshold: int,
    decision_site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Recompute the complete stage conclusion from prefix plus increment.

    The prefix statements are the already-verified statements of the
    predecessor; each new decision is authenticated and authorized
    through the existing fork-decision aggregate rules under the new
    decision site policy, and the complete statement set is re-tallied.
    """
    increment_rows: list[dict] = []
    increment_digests: list[str] = []
    for item in increment:
        digest = hashlib.sha256(item[FAC_PACKET]).hexdigest()
        increment_digests.append(digest)
        increment_rows.append(
            _aggregate_pfda_one(
                item,
                prune_policy_digest,
                fork_site_policy_digest,
                fork_threshold,
                decision_site_policy,
                validated_keyring,
                moment,
            )
        )

    full_inputs = list(prefix_inputs) + increment_digests
    working_rows = copy.deepcopy(prefix_rows)
    working_rows.extend(copy.deepcopy(increment_rows))
    status, declaration = _tally_prune_chain_rows(
        working_rows, len(prefix_rows), decision_site_policy[ADJ_THRESHOLD]
    )
    return {
        PFDA_INPUTS: full_inputs,
        PA_ITEMS: _pac_sort_rows(working_rows),
        STATUS: status,
        PFDA_DECLARATION: declaration,
    }


def _fac_assert_transition(previous: dict, verdict: dict) -> None:
    """Enforce the per-hop verdict state machine for a fork chain.

    ``insufficient`` may gain supplemental decisions and become
    ``accepted`` or ``conflicted``; an ``accepted`` head only keeps the
    identical common declaration or advances to ``conflicted`` (it
    never falls back to insufficient or swaps declarations); a
    ``conflicted`` verdict can never be masked by a later majority.
    """
    prev_status = previous[STATUS]
    new_status = verdict[STATUS]
    if prev_status == PA_STATUS_CONFLICTED:
        if new_status != PA_STATUS_CONFLICTED:
            raise _fac_chain_invalid(
                "a conflicted aggregate can never be outvoted or fall back"
            )
    elif prev_status == PA_STATUS_ACCEPTED:
        if new_status == PA_STATUS_INSUFFICIENT:
            raise _fac_chain_invalid(
                "an accepted aggregate must not fall back to insufficient"
            )
        if new_status == PA_STATUS_ACCEPTED:
            if verdict[PFDA_DECLARATION] != previous[PFDA_DECLARATION]:
                raise _fac_chain_invalid(
                    "an accepted aggregate may only keep the same common "
                    "declaration"
                )


def _fac_assert_sealer_authorized(
    old_policy: dict, new_policy: dict, issuer: str, key_version: int
) -> None:
    """The successor sealer must be authorized under both site policies."""
    if key_version not in old_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _fac_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the previous site policy"
        )
    if key_version not in new_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _fac_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the rotated site policy"
        )


def _fac_validated_increment(increment: object) -> list[dict]:
    """Validate a sealing-stage decision increment, which may be empty.

    A non-empty increment follows the exact
    :func:`aggregate_prune_fork_decisions` item rules; an empty
    increment is only meaningful for a policy rotation (the append rule
    enforces a non-empty increment when the policy is unchanged).
    """
    if not isinstance(increment, list):
        raise TypeError("increment must be a list")
    if not increment:
        return []
    return _validated_pfda_decision_items(increment)


def _fac_assert_extends(
    previous: dict, full_inputs: list[str], increment: list[dict],
    unchanged: bool,
) -> None:
    """Enforce the append-only decision prefix and disjoint identities.

    The predecessor's decision digests must remain the ordered prefix
    of the stage -- nothing is deleted, changed or reordered -- and a
    non-empty increment adds only new packet digests and new item ids.
    An unchanged policy must add at least one decision; a rotation may
    re-seal the identical sequence with an empty increment.
    """
    prefix_inputs = previous[PFDA_INPUTS]
    if unchanged and not increment:
        raise _fac_chain_invalid("an unchanged policy requires new decisions")
    if len(full_inputs) < len(prefix_inputs):
        raise _fac_chain_invalid(
            "the decision sequence must extend the predecessor"
        )
    if full_inputs[:len(prefix_inputs)] != prefix_inputs:
        raise _fac_chain_invalid(
            "the decision sequence must keep the predecessor as an ordered "
            "prefix; history must not be deleted, changed or reordered"
        )
    prefix_digests = set(prefix_inputs)
    prefix_ids = {row[ID] for row in previous[PA_ITEMS]}
    seen_digests: set[str] = set()
    seen_ids: set[str] = set()
    for item in increment:
        digest = hashlib.sha256(item[FAC_PACKET]).hexdigest()
        if digest in prefix_digests or digest in seen_digests:
            raise _fac_chain_invalid(
                "a decision packet already in the prefix must not be appended "
                "again"
            )
        seen_digests.add(digest)
        item_id = item[ID]
        if item_id in prefix_ids or item_id in seen_ids:
            raise _fac_chain_invalid(
                f"decision item id {item_id!r} is already part of the chain"
            )
        seen_ids.add(item_id)


# -- Successor packet shape ----------------------------------------------------

def _fac_bound_decisions(raw_items: object, where: str) -> list[dict]:
    """Parse the raw decision increment bound inside a successor packet.

    Each entry carries exactly ``id`` and ``decision``; packet bytes
    ride as non-empty even-length lowercase hex.  A field of the wrong
    type raises :class:`TypeError`; every key-set, value or hex fault
    raises :class:`InvalidForkAggregateChainError`.
    """
    if not isinstance(raw_items, list):
        raise TypeError(f"{where} decisions must be a list")
    validated: list[dict] = []
    for position, item in enumerate(raw_items):
        item_where = f"{where} decision {position}"
        if not isinstance(item, dict):
            raise TypeError(f"{item_where} must be an object")
        if set(item.keys()) != _FAC_DECISION_ITEM_KEYS:
            raise _fac_chain_invalid(
                f"{item_where} must contain exactly the keys 'decision' and "
                "'id'"
            )
        item_id = item[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{item_where} id must be a str")
        if item_id == "":
            raise _fac_chain_invalid(f"{item_where} id must be non-empty")
        packet_hex = item[FAC_PACKET]
        if not isinstance(packet_hex, str):
            raise TypeError(f"{item_where} decision must be a str")
        try:
            packet = _hex_bytes(packet_hex)
        except ValueError as exc:
            raise _fac_chain_invalid(
                f"{item_where} decision must be non-empty even-length "
                "lowercase hex"
            ) from exc
        validated.append({ID: item_id, FAC_PACKET: packet})
    return validated


def _fac_validated_rows(raw_rows: object, where: str) -> list[dict]:
    """Validate the bound aggregate rows of a fork successor payload.

    The row contract is the one :func:`aggregate_prune_fork_decisions`
    binds, but every structural fault raises
    :class:`InvalidForkAggregateChainError` and a wrong JSON type raises
    :class:`TypeError`.
    """
    if not isinstance(raw_rows, list):
        raise TypeError(f"{where} items must be a list")
    if not raw_rows:
        raise _fac_chain_invalid(f"{where} items must be a non-empty list")
    parsed_rows: list[dict] = []
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        row_where = f"{where} item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be an object")
        if set(row.keys()) != _PFDA_ROW_KEYS:
            raise _fac_chain_invalid(
                f"{row_where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{row_where} id must be a str")
        if row_id == "":
            raise _fac_chain_invalid(f"{row_where} id must be non-empty")
        if row_id in seen_ids:
            raise _fac_chain_invalid(f"{row_where} repeats an id")
        seen_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{row_where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _fac_chain_invalid(
                f"{row_where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{row_where} issuer must be a str or null")
        if site == "":
            raise _fac_chain_invalid(f"{row_where} issuer must be non-empty")
        key_version = row[KEY_VERSION]
        if isinstance(key_version, bool) or not isinstance(key_version, int):
            if key_version is not None:
                raise TypeError(
                    f"{row_where} keyVersion must be an int or null"
                )
        elif key_version <= 0:
            raise _fac_chain_invalid(
                f"{row_where} keyVersion must be positive"
            )
        if (site is None) != (key_version is None):
            raise _fac_chain_invalid(
                f"{row_where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{row_where} conclusion must be a str")
        reason = row[ADJ_REASON]
        if conclusion == PA_CONCLUSION_VALID:
            if reason is not None:
                raise _fac_chain_invalid(
                    f"{row_where} reason must be null for a valid row"
                )
        elif conclusion == PA_CONCLUSION_INVALID:
            if reason not in _PFDA_INVALID_REASONS:
                raise _fac_chain_invalid(
                    f"{row_where} reason must be one of 'invalid', "
                    "'unauthenticated' or 'unauthorized'"
                )
        elif conclusion in (
            PA_CONCLUSION_DUPLICATE, PA_CONCLUSION_CONTRADICTION
        ):
            expected = (
                REASON_DUPLICATE
                if conclusion == PA_CONCLUSION_DUPLICATE
                else REASON_CONTRADICTION
            )
            if reason != expected:
                raise _fac_chain_invalid(
                    f"{row_where} reason must match its conclusion"
                )
        else:
            raise _fac_chain_invalid(f"{row_where} conclusion is not known")
        identity_present = reason != PA_CONCLUSION_INVALID
        if identity_present:
            if site is None:
                raise _fac_chain_invalid(
                    f"{row_where} an authenticated or authorized row must "
                    "carry its issuer"
                )
        elif site is not None:
            raise _fac_chain_invalid(
                f"{row_where} an invalid row must carry no issuer"
            )
        if conclusion == PA_CONCLUSION_INVALID:
            if row[PFDA_DECLARATION] is not None:
                raise _fac_chain_invalid(
                    f"{row_where} an invalid row must carry no declaration"
                )
            declaration = None
        else:
            try:
                declaration = _validated_pfda_declaration(
                    row[PFDA_DECLARATION], f"{row_where} declaration"
                )
            except InvalidAggregateForkDecisionAggregateError as exc:
                raise _fac_chain_invalid(str(exc)) from exc
            if declaration is None:
                raise _fac_chain_invalid(
                    f"{row_where} a counted row must carry its declaration"
                )
        parsed_rows.append({
            ADJ_CONCLUSION: conclusion,
            CP_DIGEST: digest,
            ID: row_id,
            VD_ISSUER: site,
            KEY_VERSION: key_version,
            ADJ_REASON: reason,
            PFDA_DECLARATION: declaration,
        })
    return parsed_rows


def _parse_fac_successor(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate successor bytes into ``(payload, signature, increment)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, row or increment fault raises
    :class:`InvalidForkAggregateChainError`.  The predecessor, policy,
    moment, tally and signature bindings are checked by the chain
    verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("successor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _fac_chain_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _fac_chain_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_fac_keys
        )
    except json.JSONDecodeError as exc:
        raise _fac_chain_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("successor must be a JSON object")
    if set(data.keys()) != _FAC_TOP_KEYS:
        raise _fac_chain_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("successor signature must be a str")
    if not _prune_is_digest(signature):
        raise _fac_chain_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("successor payload must be an object")
    if set(payload.keys()) != _FAC_SUCCESSOR_PAYLOAD_KEYS:
        raise _fac_chain_invalid("payload must contain exactly the bound keys")

    for key in (
        FAC_ROOT_DIGEST, FAC_PREDECESSOR_DIGEST,
        PFDA_PRUNE_POLICY_DIGEST, FAC_SITE_POLICY_DIGEST,
        FAC_OLD_POLICY_DIGEST, FAC_NEW_POLICY_DIGEST,
    ):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _fac_chain_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[FAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 1:
        raise _fac_chain_invalid("payload height must be a positive integer")
    policy_version = payload[FAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _fac_chain_invalid("payload policyVersion must be positive")
    effective = payload[FAC_EFFECTIVE_AT]
    if isinstance(effective, bool) or not isinstance(effective, int):
        raise TypeError("payload effectiveAt must be an int")
    if effective < 0:
        raise _fac_chain_invalid("payload effectiveAt must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _fac_chain_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _fac_chain_invalid("payload keyVersion must be positive")
    packet_version = payload[VERSION]
    if isinstance(packet_version, bool) or not isinstance(
        packet_version, int
    ):
        raise TypeError("payload version must be an int")
    if packet_version != FORK_AGGREGATE_CHAIN_VERSION:
        raise _fac_chain_invalid("payload version must be the integer 1")

    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PA_STATUSES:
        raise _fac_chain_invalid("payload status is not known")

    inputs = payload[PFDA_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("payload inputs must be a list")
    if not inputs:
        raise _fac_chain_invalid("payload inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not isinstance(digest, str):
            raise TypeError(f"payload input {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _fac_chain_invalid(
                f"payload input {position} digest must be 64 lowercase hex "
                "characters"
            )

    rows = _fac_validated_rows(payload[ITEMS], "payload")
    if len(rows) != len(inputs):
        raise _fac_chain_invalid(
            "the items must cover every decision and vice versa"
        )
    raw_declaration = payload[PFDA_DECLARATION]
    if raw_declaration is None:
        declaration = None
    else:
        try:
            declaration = _validated_pfda_declaration(
                raw_declaration, "payload declaration"
            )
        except InvalidAggregateForkDecisionAggregateError as exc:
            raise _fac_chain_invalid(str(exc)) from exc
    if status == PA_STATUS_ACCEPTED and declaration is None:
        raise _fac_chain_invalid(
            "an accepted verdict must keep the common declaration"
        )
    if status == PA_STATUS_CONFLICTED and declaration is not None:
        raise _fac_chain_invalid(
            "a conflicted verdict must bind a null common declaration"
        )

    increment = _fac_bound_decisions(payload[FAC_DECISIONS], "payload")

    normalized_payload = {
        FAC_ROOT_DIGEST: payload[FAC_ROOT_DIGEST],
        FAC_PREDECESSOR_DIGEST: payload[FAC_PREDECESSOR_DIGEST],
        FAC_HEIGHT: height,
        PFDA_INPUTS: list(inputs),
        ITEMS: rows,
        PFDA_DECLARATION: declaration,
        STATUS: status,
        PFDA_PRUNE_POLICY_DIGEST: payload[PFDA_PRUNE_POLICY_DIGEST],
        FAC_SITE_POLICY_DIGEST: payload[FAC_SITE_POLICY_DIGEST],
        FAC_OLD_POLICY_DIGEST: payload[FAC_OLD_POLICY_DIGEST],
        FAC_NEW_POLICY_DIGEST: payload[FAC_NEW_POLICY_DIGEST],
        FAC_POLICY_VERSION: policy_version,
        FAC_EFFECTIVE_AT: effective,
        FAC_DECISIONS: [
            {ID: item[ID], FAC_PACKET: item[FAC_PACKET].hex()}
            for item in increment
        ],
        VD_ISSUER: issuer,
        KEY_VERSION: key_version,
        VERSION: FORK_AGGREGATE_CHAIN_VERSION,
    }
    if _prune_compact({TICKET_PAYLOAD: normalized_payload,
                       SIGNATURE: signature}) != raw:
        raise _fac_chain_invalid(
            "encoding is not the canonical compact form"
        )
    return normalized_payload, signature, increment


# -- Sealing a successor -------------------------------------------------------

def supersede_fork_aggregate(
    predecessor, increment, prune_policy, site_policy, old_policy, new_policy,
    keyring, moment, effective_at, issuer, version
):
    """Issue one signed supersession successor over a fork decision aggregate.

    ``predecessor`` is either the chain root (an
    :func:`aggregate_prune_fork_decisions` packet) or the previous
    successor packet.  ``increment`` is the stage's decision list in
    the exact shape of :func:`aggregate_prune_fork_decisions` items --
    each exactly a unique non-empty ``id`` and ``decision`` bytes (an
    :func:`adjudicate_prune_aggregate_forks` packet).  The stage keeps
    every predecessor decision verbatim as an ordered digest prefix and
    only appends the increment; existing statements are never deleted,
    changed or reordered.  ``prune_policy`` is the original invariant
    ``{"batch", "sites", "threshold"}`` pruning policy and
    ``site_policy`` the invariant fork-proof site policy, both fixed
    along the whole chain; ``old_policy``/``new_policy`` are the
    versioned decision site policies and carry exactly ``sites``,
    ``threshold`` and a positive ``policyVersion``: unchanged sites and
    threshold keep the version, any content change increments it by
    exactly one (the first versioned policy over a root carries
    version 1 and must equal the root's decision site policy).
    ``effective_at`` is the hop's non-negative effective moment and
    never moves backwards; ``moment`` is the issuance moment and
    ``issuer``/``version`` name the successor sealing key, which must be
    authorized under both decision policies and usable at both moments.

    The successor verdict is recomputed in full from the full history:
    supplemental decisions may move ``insufficient`` to ``accepted`` or
    ``conflicted``; an ``accepted`` head only keeps the identical common
    declaration or advances to ``conflicted`` (it never falls back or
    swaps declarations), and a ``conflicted`` verdict can never be
    masked by a later majority.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``; the payload binds the root digest, predecessor
    digest, height, the complete recomputed conclusion, the invariant
    prune and fork-proof site policy digests, the old/new decision
    policy digests, the policy version, the effective moment, the raw
    decision increment (bytes as lowercase hex), the issuer and key
    version and ``version`` (the integer 1), signed with HMAC-SHA256
    under the exact issuer/version key.  A parameter or public field
    type fault raises :class:`TypeError` (a :class:`bool` never poses
    as an int); an empty value, duplicate increment id, illegal version,
    wrong policy count or backwards moment raises :class:`ValueError`; a
    malformed root raises
    :class:`InvalidAggregateForkDecisionAggregateError`; a malformed
    successor or broken chain rule raises
    :class:`InvalidForkAggregateChainError`; a credential fault raises
    :class:`AuthenticationError`.  No file is read or written and no
    input is modified.

def _tally_pac_fork_rows(
    rows: list[dict],
) -> tuple[bool, dict[str, _PAFD_EDGE_SET]]:
    """Group authenticated rows per site by their complete edge sets.

    Two rows from one site are the same declaration only when their
    complete fork edge set -- every ``(rootDigest, predecessorDigest,
    successors)`` triple -- agrees, regardless of the proof digest.
    The smallest-id row of one identical set is the vote and extras are
    ``duplicate``, while two distinct edge sets from one site are both a
    ``contradiction``.  Returns ``(contradicted, votes)`` where
    ``votes`` maps each non-contradicting site to its one edge set.
    """
    by_site: dict[str, dict[_PAFD_EDGE_SET, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] in (
            _PAFD_CONCLUSION_VALID,
            _PAFD_CONCLUSION_DUPLICATE,
            _PAFD_CONCLUSION_CONTRADICTION,
        ):
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                _pafd_content(row), []
            ).append(row)

    contradicted = False
    votes: dict[str, _PAFD_EDGE_SET] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            ordered_groups = sorted(
                groups.values(),
                key=lambda members: min(member[ID] for member in members),
            )
            for members in ordered_groups:
                members.sort(key=lambda row: row[ID])
                members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_CONTRADICTION
                members[0][ADJ_REASON] = REASON_CONTRADICTION
                for extra in members[1:]:
                    extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            members.sort(key=lambda row: row[ID])
            members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_VALID
            members[0][ADJ_REASON] = None
            for extra in members[1:]:
                extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                extra[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
    return contradicted, votes


def adjudicate_prune_aggregate_forks(
    items, prune_policy, site_policy, keyring, moment, issuer, version
):
    """Adjudicate multi-site prune aggregate fork proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_prune_aggregate_fork_proof`.  ``prune_policy`` is the
    shared invariant original ``{"batch","sites","threshold"}`` pruning
    policy the proofs were issued against; ``site_policy`` carries
    exactly ``sites`` (a non-empty map of each authorized non-empty site
    to its non-empty set of allowed positive key versions) and
    ``threshold`` (a positive integer no greater than the site count).
    ``keyring`` follows the existing rules, ``moment`` is the
    non-negative adjudication moment and ``issuer``/``version`` name the
    adjudicator credentials.  No file is read or written and no input is
    modified.

    Every proof is first verified through the existing prune aggregate
    fork proof rules, then authorized by the exact signing site and key
    version its payload names with no fallback, then authenticated
    against the current keyring.  An invalid, unauthenticated or
    unauthorized proof rejects just that item with one fixed reason
    (``invalid-proof``, ``unauthorized-site``, ``unauthorized-version``,
    ``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired`` or ``bad-signature``) while the later items are still
    processed.  For one site the complete fork edge set counts once --
    extra proofs declaring an identical edge set are ``duplicate`` --
    while distinct valid edge sets from one site are a
    ``contradiction``.  Distinct sites must agree exactly on the
    complete fork edge set made of the root digest, the forking
    predecessor digest and the sorted legal successor digests; any
    contradiction or cross-site disagreement is ``conflicted`` with a
    null common edge set and no majority can outvote it.  A unique edge
    set backed by at least the threshold of distinct sites is
    ``accepted``; the same unique set short of the threshold stays
    ``insufficient`` but keeps that common set; with no valid vote the
    common set is null.

    The result is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``.  The payload binds
    exactly ``common`` (the sorted common fork edge set, or null),
    ``issuer``, ``items`` (the rows stably sorted by site then id, each
    carrying ``conclusion``, its authenticated ``edges`` or null, ``id``,
    ``keyVersion``, ``proofDigest``, ``reason`` and ``site``),
    ``keyVersion``, ``prunePolicyDigest``, ``proofs`` (each proof digest
    in the original input order), ``sitePolicyDigest``, ``status`` and
    ``version`` (the integer 1).  ``signature`` is the lowercase hex
    HMAC-SHA256 of the canonical compact payload bytes under the exact
    issuer/version key.

    A parameter, container or public-field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an empty
    list, an empty or duplicate id, or an illegal prune/site policy,
    threshold, moment, issuer or version raises :class:`ValueError`;
    unknown, revoked, not-yet-valid or expired adjudicator credentials
    raise :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()

    proof_digests = [
        hashlib.sha256(item[FORK_PROOF_ITEM_PROOF]).hexdigest()
        for item in validated_items
    ]
    rows = [
        _adjudicate_pac_fork_one(
            item, prune_policy_digest, validated_site_policy,
            validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _PAFD_STATUS_CONFLICTED
        common = None
    elif len(edge_sets) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(edge_sets)))
        if len(votes) >= validated_site_policy[ADJ_THRESHOLD]:
            status = _PAFD_STATUS_ACCEPTED
        else:
            status = _PAFD_STATUS_INSUFFICIENT
    else:
        status = _PAFD_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        PAFD_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        PAFD_PROOFS: proof_digests,
        PAFD_SITE_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_site_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: PRUNE_AGGREGATE_FORK_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_pafd(raw: object, invalid=_pafd_invalid) -> tuple[dict, str]:
    """Validate decision bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault is raised
    through ``invalid`` (the prune aggregate fork decision error by
    default).  The policy, tally and credential bindings are checked by
    the decision verifier.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text,
            object_pairs_hook=lambda pairs: _reject_duplicate_pafd_keys(
                pairs, invalid
            ),
        )
    except json.JSONDecodeError as exc:
        raise invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("decision must be a JSON object")
    if set(data.keys()) != _PAFD_DECISION_TOP_KEYS:
        raise invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("decision signature must be a str")
    if not _prune_is_digest(signature):
        raise invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("decision payload must be an object")
    if set(payload.keys()) != _PAFD_PAYLOAD_KEYS:
        raise invalid(
            "payload must contain exactly the keys 'common', 'issuer', "
            "'items', 'keyVersion', 'prunePolicyDigest', 'proofs', "
            "'sitePolicyDigest', 'status' and 'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise invalid("payload keyVersion must be positive")
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PAFD_STATUSES:
        raise invalid("payload status is not a known status")
    for field in (PAFD_PRUNE_POLICY_DIGEST, PAFD_SITE_POLICY_DIGEST):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )

    proofs = payload[PAFD_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError("payload proofs must be a list")
    if not proofs:
        raise invalid("payload proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"payload proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise invalid(
                f"payload proof {position} digest must be 64 lowercase hex "
                "characters"
            )

    raw_rows = payload[ITEMS]
    if not isinstance(raw_rows, list):
        raise TypeError("payload items must be a list")
    if not raw_rows:
        raise invalid("payload items must be non-empty")
    parsed_rows: list[dict] = []
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        where = f"payload item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PAFD_ROW_KEYS:
            raise invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'edges', 'id', 'keyVersion', 'proofDigest', 'reason' and "
                "'site'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise invalid(f"{where} id must be non-empty")
        if row_id in seen_ids:
            raise invalid(f"{where} repeats an id")
        seen_ids.add(row_id)
        digest = row[PAFD_FORK_PROOF_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} proofDigest must be a str")
        if not _prune_is_digest(digest):
            raise invalid(
                f"{where} proofDigest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None:
            if not isinstance(site, str):
                raise TypeError(f"{where} site must be a str or null")
            if site == "":
                raise invalid(f"{where} site must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise invalid(
                f"{where} site and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        if conclusion not in _PAFD_CONCLUSIONS:
            raise invalid(f"{where} conclusion is not known")
        reason = row[ADJ_REASON]
        if conclusion == _PAFD_CONCLUSION_VALID:
            if reason is not None:
                raise invalid(
                    f"{where} reason must be null for a valid item"
                )
        else:
            if not isinstance(reason, str):
                raise TypeError(f"{where} reason must be a str")
            if reason not in _PAFD_REASONS:
                raise invalid(f"{where} reason is not known")
        if conclusion == _PAFD_CONCLUSION_INVALID:
            if reason not in _PAFD_INVALID_REASONS:
                raise invalid(
                    f"{where} reason does not match an invalid item"
                )
        elif conclusion != _PAFD_CONCLUSION_VALID:
            if reason != conclusion:
                raise invalid(
                    f"{where} reason must match its conclusion"
                )

        raw_edges = row[PAFD_EDGES]
        if raw_edges is not None:
            if not isinstance(raw_edges, list):
                raise TypeError(f"{where} edges must be a list or null")
            if not raw_edges:
                raise invalid(
                    f"{where} edges must be non-empty for an authenticated "
                    "proof"
                )
            row_edges = [
                _validated_pafd_edge(value, where, invalid) for value in raw_edges
            ]
            triples = _pac_fork_edge_triples(row_edges)
            if len(set(triples)) != len(triples):
                raise invalid(f"{where} edges must be unique")
            if list(triples) != sorted(triples):
                raise invalid(f"{where} edges must be sorted ascending")
        identity_expected = reason != _PAFD_REASON_INVALID_PROOF
        if identity_expected:
            if site is None or raw_edges is None:
                raise invalid(
                    f"{where} an authenticated proof must carry its site and "
                    "fork edges"
                )
        else:
            if site is not None or raw_edges is not None:
                raise invalid(
                    f"{where} an invalid-proof item must carry no site or "
                    "fork edges"
                )
        parsed_rows.append(
            {
                ADJ_CONCLUSION: conclusion,
                PAFD_EDGES: (
                    None if raw_edges is None else [dict(edge)
                                                    for edge in row_edges]
                ),
                ID: row_id,
                KEY_VERSION: row_key_version,
                PAFD_FORK_PROOF_DIGEST: digest,
                ADJ_REASON: reason,
                VD_ISSUER: site,
            }
        )

    common = payload[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError("payload common must be a list or null")
        if not common:
            raise invalid(
                "a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(value, "payload common", invalid)
            for value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise invalid(
                "payload common edges must be unique and sorted ascending"
            )

    decision_version = payload[VERSION]
    if isinstance(decision_version, bool) or not isinstance(
        decision_version, int
    ):
        raise TypeError("payload version must be an int")
    if decision_version != PRUNE_AGGREGATE_FORK_DECISION_VERSION:
        raise invalid("payload version must be the integer 1")

    if _prune_compact(data) != raw:
        raise invalid("encoding is not the canonical compact form")
    return payload, signature


def _reconcile_pafd(
    payload: dict, threshold: int, invalid=_pafd_invalid,
    positional_proofs: bool = False,
) -> str:
    """Re-derive every aggregate binding of a parsed fork decision.

    Re-tallies the per-proof rows the signature covers -- row ordering,
    proof digests, duplicate/contradiction conclusions, the cross-site
    complete-edge-set agreement, the threshold acceptance and the
    claimed common set -- without seeing any fork proof.  Any mismatch
    raises :class:`InvalidAggregateForkDecisionError`; otherwise the
    derived status is returned.

    With ``positional_proofs`` the bound ``proofs`` vector must match the
    sorted per-row digests term by term (so a reordering that is then
    re-signed is rejected); otherwise the two digest multisets only must
    agree.
    """
    rows = payload[ITEMS]
    proofs = payload[PAFD_PROOFS]
    if len(rows) != len(proofs):
        raise invalid(
            "the items must cover every proof and vice versa"
        )
    expected_order = sorted(
        rows,
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        ),
    )
    if [row[ID] for row in expected_order] != [row[ID] for row in rows]:
        raise invalid("items must be sorted by site then id")
    row_digests = [row[PAFD_FORK_PROOF_DIGEST] for row in rows]
    if positional_proofs:
        if row_digests != proofs:
            raise invalid(
                "the bound proof digests must correspond term by term to "
                "the sorted items"
            )
    elif sorted(row_digests) != sorted(proofs):
        raise invalid(
            "the bound proof digests must equal the per-item digests"
        )

    by_site: dict[str, dict[_PAFD_EDGE_SET, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] == _PAFD_CONCLUSION_INVALID:
            continue
        by_site.setdefault(row[VD_ISSUER], {}).setdefault(
            _pafd_content(row), []
        ).append(row)

    contradicted = False
    votes: dict[str, _PAFD_EDGE_SET] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            expected_conclusion = _PAFD_CONCLUSION_CONTRADICTION
            expected_reason = REASON_CONTRADICTION
        else:
            expected_conclusion = _PAFD_CONCLUSION_VALID
            expected_reason = None
            votes[site] = next(iter(groups.keys()))
        for members_raw in groups.values():
            members = sorted(members_raw, key=lambda row: row[ID])
            for index, row in enumerate(members):
                if index == 0:
                    if row[ADJ_CONCLUSION] != expected_conclusion:
                        raise invalid(
                            f"item {row[ID]!r} has the wrong conclusion"
                        )
                    if row[ADJ_REASON] != expected_reason:
                        raise invalid(
                            f"item {row[ID]!r} has the wrong reason"
                        )
                else:
                    if row[ADJ_CONCLUSION] != _PAFD_CONCLUSION_DUPLICATE:
                        raise invalid(
                            f"item {row[ID]!r} must be a duplicate"
                        )
                    if row[ADJ_REASON] != REASON_DUPLICATE:
                        raise invalid(
                            f"item {row[ID]!r} must carry the duplicate "
                            "reason"
                        )
            representative = members[0]
            for row in members[1:]:
                if _pac_fork_edge_triples(
                    row[PAFD_EDGES]
                ) != _pac_fork_edge_triples(representative[PAFD_EDGES]):
                    raise invalid(
                        f"item {row[ID]!r} duplicates a proof with a "
                        "different fork edge set"
                    )

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _PAFD_STATUS_CONFLICTED
        expected_common = None
    elif len(edge_sets) == 1 and len(votes) >= threshold:
        status = _PAFD_STATUS_ACCEPTED
        expected_common = _sorted_pac_fork_edge_objects(
            next(iter(edge_sets))
        )
    elif len(edge_sets) == 1:
        status = _PAFD_STATUS_INSUFFICIENT
        expected_common = _sorted_pac_fork_edge_objects(
            next(iter(edge_sets))
        )
    else:
        status = _PAFD_STATUS_INSUFFICIENT
        expected_common = None

    if payload[STATUS] != status:
        raise invalid("the status does not match the tallied items")
    if payload[PAFD_COMMON] != expected_common:
        raise invalid(
            "the bound common edge set does not match the tallied items"
        )
    return status

    short of the threshold it stays ``insufficient`` but keeps that
    declaration; with no valid vote the declaration is null.
    """
    # site -> content bytes -> list of (from-prefix flag, row)
    by_site: dict[str, dict[bytes, list[tuple[bool, dict]]]] = {}
    for position, row in enumerate(rows):
        if row[ADJ_CONCLUSION] in (
            PA_CONCLUSION_VALID,
            PA_CONCLUSION_DUPLICATE,
            PA_CONCLUSION_CONTRADICTION,
        ):
            content = _prune_compact(row[PBA_DECLARATION])
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                content, []
            ).append((position < prefix_count, row))

    contradicted = False
    votes: dict[str, bytes] = {}
    representatives: dict[str, dict] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            ordered_groups = sorted(
                groups.values(),
                key=lambda members: min(member[1][ID] for member in members),
            )
            for members in ordered_groups:
                members.sort(key=lambda member: member[1][ID])
                members[0][1][ADJ_CONCLUSION] = PA_CONCLUSION_CONTRADICTION
                members[0][1][ADJ_REASON] = REASON_CONTRADICTION
                for _from_prefix, extra in members[1:]:
                    extra[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            prefix_members = [
                member for member in members if member[0]
            ]
            candidates = prefix_members or members
            winner = min(candidates, key=lambda member: member[1][ID])
            winner[1][ADJ_CONCLUSION] = PA_CONCLUSION_VALID
            winner[1][ADJ_REASON] = None
            for from_prefix, member in members:
                if member is winner[1]:
                    continue
                member[ADJ_CONCLUSION] = PA_CONCLUSION_DUPLICATE
                member[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
            representatives[site] = winner[1]

    contents = set(votes.values())
    if contradicted or len(contents) > 1:
        return PA_STATUS_CONFLICTED, None
    if len(contents) == 1:
        common_declaration = copy.deepcopy(
            min(representatives.values(), key=lambda row: row[ID])[
                PBA_DECLARATION
            ]
        )
        if len(votes) >= threshold:
            return PA_STATUS_ACCEPTED, common_declaration
        return PA_STATUS_INSUFFICIENT, common_declaration
    return PA_STATUS_INSUFFICIENT, None


def _pac_recompute(
    prefix_inputs: list[str],
    prefix_rows: list[dict],
    increment: list[dict],
    prune_policy_digest: str,
    prune_threshold: int,
    site_policy: dict,
    validated_keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Recompute the complete stage conclusion from prefix plus increment.

    The prefix statements are the already-verified statements of the
    predecessor; each new handover is run through the existing
    aggregation rules and the complete statement set is then re-tallied.
    """
    increment_rows: list[dict] = []
    increment_digests: list[str] = []
    for item in increment:
        digest = hashlib.sha256(item[PBA_PACKET]).hexdigest()
        increment_digests.append(digest)
        increment_rows.append(
            _aggregate_prune_batch_one(
                item, digest, prune_policy_digest, prune_threshold,
                site_policy, validated_keyring, moment,
            )
        )

    full_inputs = list(prefix_inputs) + increment_digests
    working_rows = copy.deepcopy(prefix_rows)
    working_rows.extend(copy.deepcopy(increment_rows))
    status, declaration = _tally_prune_chain_rows(
        working_rows, len(prefix_rows), site_policy[ADJ_THRESHOLD]
    )
    return {
        PBA_INPUTS: full_inputs,
        PA_ITEMS: _pac_sort_rows(working_rows),
        STATUS: status,
        PBA_DECLARATION: declaration,
    }


def _pac_assert_transition(previous: dict, verdict: dict) -> None:
    """Enforce the per-hop verdict state machine.

    ``insufficient`` may gain supplemental evidence and become
    ``accepted`` or ``conflicted``; an ``accepted`` head only keeps the
    identical common declaration or advances to ``conflicted`` (it
    never falls back to insufficient or swaps declarations); a
    ``conflicted`` verdict can never be masked by a later majority.
    """
    prev_status = previous[STATUS]
    new_status = verdict[STATUS]
    if prev_status == PA_STATUS_CONFLICTED:
        if new_status != PA_STATUS_CONFLICTED:
            raise _pac_chain_invalid(
                "a conflicted aggregate can never be outvoted or fall back"
            )
    elif prev_status == PA_STATUS_ACCEPTED:
        if new_status == PA_STATUS_INSUFFICIENT:
            raise _pac_chain_invalid(
                "an accepted aggregate must not fall back to insufficient"
            )
        if new_status == PA_STATUS_ACCEPTED:
            if verdict[PBA_DECLARATION] != previous[PBA_DECLARATION]:
                raise _pac_chain_invalid(
                    "an accepted aggregate may only keep the same common "
                    "declaration"
                )


def _pac_assert_sealer_authorized(
    old_policy: dict, new_policy: dict, issuer: str, key_version: int
) -> None:
    """The successor sealer must be authorized under both site policies."""
    if key_version not in old_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _pac_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the previous site policy"
        )
    if key_version not in new_policy[ADJ_SITES].get(issuer, frozenset()):
        raise _pac_chain_invalid(
            f"sealer {issuer!r} version {key_version} is not authorized by "
            "the rotated site policy"
        )


def _pac_validated_increment(increment: object) -> list[dict]:
    """Validate a sealing-stage handover increment, which may be empty.

    A non-empty increment follows the exact
    :func:`aggregate_prune_batches` item rules; an empty increment is
    only meaningful for a policy rotation (the append rule enforces a
    non-empty increment when the policy is unchanged).
    """
    if not isinstance(increment, list):
        raise TypeError("increment must be a list")
    if not increment:
        return []
    return _validated_prune_batch_items(increment)


def _pac_assert_extends(
    previous: dict, full_inputs: list[str], increment: list[dict],
    unchanged: bool,
) -> None:
    """Enforce the append-only handover prefix and disjoint identities.

    The predecessor's handover digests must remain the ordered prefix
    of the stage -- nothing is deleted, changed or reordered -- and a
    non-empty increment adds only new packet digests and new item ids.
    An unchanged policy must add at least one handover; a rotation may
    re-seal the identical sequence with an empty increment.
    """
    prefix_inputs = previous[PBA_INPUTS]
    if unchanged and not increment:
        raise _pac_chain_invalid("an unchanged policy requires new handovers")
    if len(full_inputs) < len(prefix_inputs):
        raise _pac_chain_invalid(
            "the handover sequence must extend the predecessor"
        )
    if full_inputs[:len(prefix_inputs)] != prefix_inputs:
        raise _pac_chain_invalid(
            "the handover sequence must keep the predecessor as an ordered "
            "prefix; history must not be deleted, changed or reordered"
        )
    prefix_digests = set(prefix_inputs)
    prefix_ids = {row[ID] for row in previous[PA_ITEMS]}
    seen_digests: set[str] = set()
    seen_ids: set[str] = set()
    for item in increment:
        digest = hashlib.sha256(item[PBA_PACKET]).hexdigest()
        if digest in prefix_digests or digest in seen_digests:
            raise _pac_chain_invalid(
                "a handover packet already in the prefix must not be appended "

            )
    elif conclusion != _PAFD_CONCLUSION_VALID:
        if reason != conclusion:
            raise invalid(
                f"{where} entry reason must match its conclusion"
            )
    raw_edges = value[PAFD_EDGES]
    if raw_edges is not None:
        if not isinstance(raw_edges, list):
            raise TypeError(f"{where} entry edges must be a list or null")
        if not raw_edges:
            raise invalid(
                f"{where} entry edges must be non-empty for an "
                "authenticated proof"
            )
        edges = [
            _validated_pafd_edge(edge_value, where, invalid)
            for edge_value in raw_edges
        ]
        triples = _pac_fork_edge_triples(edges)
        if len(set(triples)) != len(triples):
            raise invalid(f"{where} entry edges must be unique")
        if list(triples) != sorted(triples):
            raise invalid(
                f"{where} entry edges must be sorted ascending"
            )
    else:
        edges = None
    identity_expected = reason != _PAFD_REASON_INVALID_PROOF
    if identity_expected:
        if site is None or edges is None:
            raise invalid(
                f"{where} an authenticated entry must carry its site and "
                "fork edges"
            )
    elif site is not None or edges is not None:
        raise invalid(
            f"{where} an invalid-proof entry must carry no site or fork "
            "edges"
        )
    return {
        ADJ_CONCLUSION: conclusion,
        CP_DIGEST: digest,
        PAFD_EDGES: edges,
        ID: entry_id,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


def _validated_pfda_declaration(
    value: object, where: str, invalid=_pfda_invalid,
    positional_proofs: bool = False,
) -> dict | None:
    """Structurally validate one complete declaration into a fresh dict.

    The declaration carries exactly ``common`` (the common fork edge
    set, or null), ``conclusions`` (the per-item conclusion entries,
    sorted by site then id), ``proofs`` (the proof digest vector) and
    ``status``; a conflicted status binds no common set and an accepted
    status must bind one.  With ``positional_proofs`` the proof vector
    must match the sorted per-entry digests term by term; otherwise only
    the two digest multisets must agree.
    """
    if value is None:
        return None
    if not isinstance(value, dict):
        raise TypeError(f"{where} must be an object or null")
    if set(value.keys()) != _PFDA_DECLARATION_KEYS:
        raise invalid(
            f"{where} must contain exactly the keys 'common', "
            "'conclusions', 'proofs' and 'status'"
        )
    status = value[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} status must be a str")
    if status not in _PAFD_STATUSES:
        raise invalid(f"{where} status is not a known status")

    common = value[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError(f"{where} common must be a list or null")
        if not common:
            raise invalid(
                f"{where} a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(edge_value, f"{where} common", invalid)
            for edge_value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise invalid(
                f"{where} common edges must be unique and sorted ascending"
            )
    else:
        common_edges = None
    if status == _PAFD_STATUS_CONFLICTED and common is not None:
        raise invalid(
            f"{where} a conflicted declaration must bind no common set"
        )
    if status == _PAFD_STATUS_ACCEPTED and common is None:
        raise invalid(
            f"{where} an accepted declaration must bind its common set"
        )

    raw_entries = value[PFDA_CONCLUSIONS]
    if not isinstance(raw_entries, list):
        raise TypeError(f"{where} conclusions must be a list")
    if not raw_entries:
        raise invalid(f"{where} conclusions must be non-empty")
    entries = [
        _validated_pfda_declaration_entry(entry_value, where, invalid)
        for entry_value in raw_entries
    ]
    entry_ids = [entry[ID] for entry in entries]
    if len(set(entry_ids)) != len(entry_ids):
        raise invalid(f"{where} conclusions must not repeat an id")
    expected_order = sorted(
        entries,
        key=lambda entry: (
            entry[VD_ISSUER] is not None,
            entry[VD_ISSUER] or "",
            entry[ID],
        ),
    )
    if [entry[ID] for entry in expected_order] != entry_ids:
        raise invalid(
            f"{where} conclusions must be sorted by site then id"
        )

    proofs = value[PFDA_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError(f"{where} proofs must be a list")
    if not proofs:
        raise invalid(f"{where} proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"{where} proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise invalid(
                f"{where} proof {position} digest must be 64 lowercase hex "
                "characters"
            )
    if len(proofs) != len(entries):
        raise invalid(
            f"{where} the conclusions must cover every proof and vice versa"
        )
    entry_digests = [entry[CP_DIGEST] for entry in entries]
    if positional_proofs:
        if proofs != entry_digests:
            raise invalid(
                f"{where} the bound proof digests must correspond term by "
                "term to the sorted conclusions"
            )
    elif sorted(proofs) != sorted(entry_digests):
        raise invalid(
            f"{where} the bound proof digests must equal the per-entry "
            "digests"
        )

    return {
        PAFD_COMMON: common_edges,
        PFDA_CONCLUSIONS: entries,
        PFDA_PROOFS: list(proofs),
        STATUS: status,
    }


def _parse_pfda(raw: object) -> tuple[dict, str]:
    """Validate aggregate bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a public field of the wrong JSON type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, ordering, row-shape or
    declaration-shape fault raises
    :class:`InvalidAggregateForkDecisionAggregateError`.  The policy
    digests, tally and credential bindings are checked by
    :func:`verify_prune_fork_decision_aggregate`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("aggregate packet must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pfda_invalid(
            "aggregate packet must end with the closing brace, no "
            "trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pfda_invalid("aggregate packet is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pfda_keys
        )
    except json.JSONDecodeError as exc:
        raise _pfda_invalid("aggregate packet is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("aggregate packet must be a JSON object")
    if set(data.keys()) != _PFDA_TOP_KEYS:
        raise _pfda_invalid(
            "aggregate packet must contain exactly the keys 'payload' and "
            "'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("aggregate packet signature must be a str")
    if not _prune_is_digest(signature):
        raise _pfda_invalid(
            "aggregate packet signature must be 64 lowercase hex characters"
        )

    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("aggregate packet payload must be an object")
    if set(payload.keys()) != _PFDA_PAYLOAD_KEYS:
        raise _pfda_invalid(
            "aggregate packet payload must contain exactly the keys "
            "'inputs', 'issuer', 'items', 'keyVersion', "
            "'prunePolicyDigest', 'sitePolicyDigest', "
            "'decisionSitePolicyDigest', 'declaration', 'status' and "
            "'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("aggregate payload issuer must be a str")
    if issuer == "":
        raise _pfda_invalid("aggregate payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("aggregate payload keyVersion must be an int")
    if key_version <= 0:
        raise _pfda_invalid("aggregate payload keyVersion must be positive")
    for field in (
        PFDA_PRUNE_POLICY_DIGEST,
        PFDA_SITE_POLICY_DIGEST,
        PFDA_DECISION_SITE_POLICY_DIGEST,
    ):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"aggregate payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"aggregate payload {field} must be 64 lowercase hex "
                "characters"
            )
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("aggregate status must be a str")
    if status not in _PA_STATUSES:
        raise _pfda_invalid("aggregate status is not a known status")
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("aggregate payload version must be an int")
    if version != PRUNE_FORK_DECISION_AGGREGATE_VERSION:
        raise _pfda_invalid("aggregate payload version must be the integer 1")

    inputs = payload[PFDA_INPUTS]
    if not isinstance(inputs, list):
        raise TypeError("aggregate inputs must be a list")
    if not inputs:
        raise _pfda_invalid("aggregate inputs must be a non-empty list")
    for position, digest in enumerate(inputs):
        if not isinstance(digest, str):
            raise TypeError(f"aggregate input {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"aggregate input {position} digest must be 64 lowercase "
                "hex characters"
            )

    rows = payload[ITEMS]
    if not isinstance(rows, list):
        raise TypeError("aggregate items must be a list")
    if not rows:
        raise _pfda_invalid("aggregate items must be a non-empty list")
    if len(rows) != len(inputs):
        raise _pfda_invalid(
            "the items must cover every input and vice versa"
        )
    seen_row_ids: set[str] = set()
    parsed_rows: list[dict] = []
    for position, row in enumerate(rows):
        where = f"aggregate item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PFDA_ROW_KEYS:
            raise _pfda_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'digest', 'id', 'issuer', 'keyVersion', 'reason' and "
                "'declaration'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _pfda_invalid(f"{where} id must be non-empty")
        if row_id in seen_row_ids:
            raise _pfda_invalid(f"{where} repeats an id")
        seen_row_ids.add(row_id)
        digest = row[CP_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pfda_invalid(
                f"{where} digest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None and not isinstance(site, str):
            raise TypeError(f"{where} issuer must be a str or null")
        if site == "":
            raise _pfda_invalid(f"{where} issuer must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _pfda_invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise _pfda_invalid(
                f"{where} issuer and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]

def _pac_fork_proof_edges(payload: dict) -> list[dict]:
    """The complete fork edge set a verified fork proof binds.

    The proof parser already validated every fork entry, its ordering
    and its successor set, so the entries are copied verbatim in the
    report's own canonical (root, predecessor, successor) order.
    """
    return [
        _pac_fork_edge_object(fork)
        for fork in payload[FORK_PROOF_REPORT][CHAINS_FORKS]
    ]


def _pac_fork_edge_triples(
    edges: list[dict],
) -> tuple[tuple[str, str, tuple[str, ...]], ...]:
    """Order-preserving edge objects to comparable triples."""
    return tuple(
        (
            edge[PAC_ROOT_DIGEST],
            edge[PAC_PREDECESSOR_DIGEST],
            tuple(edge[PAC_BATCH_SUCCESSORS]),
        )
        for edge in edges
    )


def _sorted_pac_fork_edge_objects(
    triples: set | frozenset,
) -> list[dict]:
    """Unique fork edges sorted by (rootDigest, predecessorDigest, ...)."""
    return [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: list(successors),
        }
        for root_digest, predecessor, successors in sorted(triples)
    ]


def _validated_pafd_edge(value: object, where: str, invalid=_pafd_invalid) -> dict:
    """Validate one bound fork edge object into a fresh ordered dict.

    Every non-type structural fault is raised through ``invalid`` (the
    prune aggregate fork decision error by default), so the same
    validation backs the chain fork decision packet.
    """
    if not isinstance(value, dict):
        raise TypeError(f"{where} edge must be an object")
    if set(value.keys()) != _PAFD_EDGE_KEYS:
        raise invalid(
            f"{where} edge must contain exactly the keys 'predecessorDigest', "
            "'rootDigest' and 'successors'"
        )
    root_digest = value[PAC_ROOT_DIGEST]
    predecessor = value[PAC_PREDECESSOR_DIGEST]
    successors = value[PAC_BATCH_SUCCESSORS]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} edge rootDigest must be a str")
    if not isinstance(predecessor, str):
        raise TypeError(f"{where} edge predecessorDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise invalid(
            f"{where} edge rootDigest must be 64 lowercase hex characters"
        )
    if not _prune_is_digest(predecessor):
        raise invalid(
            f"{where} edge predecessorDigest must be 64 lowercase hex "
            "characters"
        )
    if not isinstance(successors, list):
        raise TypeError(f"{where} edge successors must be a list")
    if not successors:
        raise invalid(f"{where} edge successors must be non-empty")
    for position, successor in enumerate(successors):
        if not isinstance(successor, str):
            raise TypeError(
                f"{where} edge successor {position} must be a str"
            )
        if not _prune_is_digest(successor):
            raise invalid(
                f"{where} edge successor {position} must be 64 lowercase "
                "hex characters"
            )
    if successors != sorted(successors) or len(set(successors)) != len(
        successors
    ):
        raise invalid(
            f"{where} edge successors must be unique and sorted ascending"
        )
    return {
        PAC_ROOT_DIGEST: root_digest,
        PAC_PREDECESSOR_DIGEST: predecessor,
        PAC_BATCH_SUCCESSORS: list(successors),
    }


def _pafd_row(
    item_id: str,
    proof_digest: str,
    site: str | None,
    key_version: int | None,
    edges: list[dict] | None,
    conclusion: str,
    reason: str | None,
) -> dict:
    """One per-proof decision row with the fixed bound key set."""
    return {
        ADJ_CONCLUSION: conclusion,
        PAFD_EDGES: edges,
        ID: item_id,
        KEY_VERSION: key_version,
        PAFD_FORK_PROOF_DIGEST: proof_digest,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


